package servicio;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import dao.EventoPagoDAO;import negocio.*;import org.junit.jupiter.api.Test;
class AuditoriaWebhookMercadoPagoServiceTest {@Test void conservaFirmaInvalidaYMarcaError(){EventoPagoDAO dao=mock(EventoPagoDAO.class);when(dao.registrarSiNuevo(any())).thenAnswer(i->{EventoPago e=i.getArgument(0);e.setId(9);return true;});var s=new AuditoriaWebhookMercadoPagoService(dao);EventoPago e=s.recibir("req-1","123","{}",false);assertFalse(e.isFirmaValida());assertEquals(EstadoProcesamientoEventoPago.ERROR,e.getEstadoProcesamiento());s.error(e,"Firma invalida.");verify(dao).marcarError(9,"Firma invalida.");}@Test void entregaDuplicadaRecuperaEventoExistente(){EventoPagoDAO dao=mock(EventoPagoDAO.class);when(dao.registrarSiNuevo(any())).thenReturn(false);EventoPago existente=new EventoPago();existente.setId(7);when(dao.buscar(eq("MERCADO_PAGO"),startsWith("delivery:"))).thenReturn(existente);assertSame(existente,new AuditoriaWebhookMercadoPagoService(dao).recibir("req-2","456","{}",true));}}